-- (bim-ootb viewer/ — the file the LIVE Viewer actually fetches for HHS, GH override per index.html)
--
-- Root cause: VIEWER_FIND_PANEL_ROOM_ACCURACY.md §2b (2026-07-11) — this file's spatial_structure
-- was still the stale pre-refinement 14-row COMPILED-only set (from an earlier compile_rooms.py
-- pass); the corrected ~105-row §DOOR-PARTITION set only ever landed in the SEPARATE Modeller-side
-- file modeller/HHS_ARC.db (unmerged branch fable/modeller-lod400-livewire @790b069, itself carried
-- to main via prompts/Modeller/DISC_Walker/embed8_scripts/ROOM002_HHS_spatial_structure_carry.sql).
-- Same source of truth, different target file/path — this script is that SAME 109-row payload
-- (byte-identical INSERT rows), re-targeted at the Viewer's own buildings/ copy.
--
-- NOTE (checked before writing this): an uncommitted, locally-modified copy of
-- buildings/HHS_Office_Federated_extracted.db was found sitting in the shared bim-ootb checkout
-- (61 IfcSpace rows, object_type=COMPILED, predefined_type INTERNAL/INTERNAL_DOORPART/INTERNAL_SMALL)
-- — inspected and confirmed it does NOT match modeller/HHS_ARC.db's 105-row corrected set (different
-- row count, looks like an earlier/intermediate compile pass, not this task's target). Not used as
-- a source here; this script's 109 rows are copied verbatim from modeller/HHS_ARC.db instead.
--
-- Applied automatically at runtime by viewer/scene.js's A._applyPendingPatch (fetched + db.run() on
-- every buildings/*.db open, see that function's header) — NOT a manual sqlite3 step for live users.
-- Source: fable/modeller-lod400-livewire modeller/HHS_ARC.db, spatial_structure table, 109 rows.
-- Manual apply (dev/offline): sqlite3 buildings/HHS_Office_Federated_extracted.db < buildings/patches/HHS_Office_Federated_extracted.db.sql
-- Verify: sqlite3 buildings/HHS_Office_Federated_extracted.db "SELECT COUNT(*) FROM spatial_structure"  -- expect 109
-- ════════════════════════════════════════════════════════

CREATE TABLE IF NOT EXISTS spatial_structure (guid TEXT, type TEXT, name TEXT, parent_guid TEXT,
                     object_type TEXT, predefined_type TEXT, center_x REAL, center_y REAL, center_z REAL,
                     size_x REAL, size_y REAL, size_z REAL);

DELETE FROM spatial_structure;


-- ROOM_LENS_VISUAL_HIGHLIGHT_SPEC.md sec21/22: mesh-derived walkable raster, built AFTER
